/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"production-level-11","number":11,"title":"Module 11 — Arrangement Labs: R&B, Reggae, Club","skillBand":"Textbook","duration":"From the course textbook","summary":"- Comp multi-take vocal toplines in Live 12 Take Lanes without destroying natural laid-back pocket. - Sculpt arrangement space and silence on the timeline to spotlight harmonic chord movement.","modules":[{"id":"production-m-11-1","code":"11","title":"Arrangement Genre Labs: Linear Specialty (R&B, Reggae/Dub, Club Linearly)","blurb":"- Comp multi-take vocal toplines in Live 12 Take Lanes without destroying natural laid-back pocket. - Sculpt arrangement space and silence on the timeline to spotlight harmonic chord movement.","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"production-l-o-15","title":"Section overview","blocks":[{"type":"step","title":"overview","blocks":[{"type":"heading","text":"Module 11 — Arrangement Genre Labs: Linear Specialty (R&B, Reggae/Dub, Club Linearly)","level":1},{"type":"callout","variant":"key","title":"Note","html":"[!NOTE] <strong>Genre Labs — Skip Anytime.</strong>   Completing or skipping these labs does not block course progression or capstone deliverables."},{"type":"prose","html":"<strong>Intent:</strong> Master linear arrangement workflows for vocal pocket comping, automated dub delay throws, and 32-bar linear club blocks. Compose house, techno, dubstep, or drum &amp; bass directly on the horizontal ruler from Bar 1 without using Session View clip slots.   <strong>Primary Source References:</strong> Ableton Live 12 Reference Manual (Ch. 21: Comping, Ch. 25: Automation); Beat Kitchen (Ch. 6: <em>Arrangement and Energy Management</em>); <em>PML - Guide to Electronic Arrangements.pdf</em>; <em>Music-Production-Songwriting-Knowledgebase.md</em> (§8.7, §9.3–9.5); <em>The Art of Turnarounds.pdf</em>."},{"type":"heading","text":"Section 11.1 — G-RNB-ARR · R&B Vocal (skippable)","level":1},{"type":"prose","html":"<strong>Section ID:</strong> <code>production-m11-1</code>   <strong>Learning Outcomes:</strong>"},{"type":"list","items":["Comp multi-take vocal toplines in Live 12 Take Lanes without destroying natural laid-back pocket.","Sculpt arrangement space and silence on the timeline to spotlight harmonic chord movement.","Record and automate expressive vocal ad-lib passes across final chorus blocks.","Construct a 32-bar linear contemporary R&amp;B arrangement."],"ordered":false}]}],"minutes":8},{"id":"production-l11-1-1","title":"11.1.1 — Comping the R&B Topline in Take Lanes","blocks":[{"type":"step","title":"11.1.1 — Comping the R&B Topline in Take Lanes","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Assemble pristine, emotionally expressive vocal takes using Live 12 Take Lanes.  "}]},{"type":"step","title":"1. Comping Workflow for R&B Toplines","blocks":[{"type":"list","items":["Set the Loop Brace (<code>Ctrl + L</code>) over the 16-bar Verse/Chorus block.","Record 5 continuous passes on Track 1 (<code>VOX_LEAD</code>).","Press <strong><code>Ctrl + Alt + U</code></strong> to reveal all Take Lanes.","Listen critically to each vocal run, vibrato tail, and breath.","Use the Draw Tool (<code>B</code>) to highlight and promote the strongest phrases into the Main Track Lane.","Verify that automatic crossfades between adjacent vocal slices are smooth and click-free."],"ordered":true}]}],"minutes":8},{"id":"production-l11-1-2","title":"11.1.2 — Dynamic Space and Silence on the Timeline","blocks":[{"type":"step","title":"11.1.2 — Dynamic Space and Silence on the Timeline","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Leave acoustic breathing room on the ruler for lush keyboard harmonies and bass slides.  "}]},{"type":"step","title":"1. The Power of the Rest in R&B","blocks":[{"type":"prose","html":"In contemporary R&amp;B production, silence is an active instrument:"},{"type":"list","items":["Do NOT crowd every beat with continuous vocal runs.","Leave 1 to 2 beats of complete vocal silence before major chord changes.","In these vocal gaps, spotlight subtle 16th-note Rhodes chord rolls, sub-bass 808 slides, or a delicate stereo rimshot."],"ordered":false}]}],"minutes":8},{"id":"production-l11-1-3","title":"11.1.3 — The Ad-Lib Lane After the Final Hook","blocks":[{"type":"step","title":"11.1.3 — The Ad-Lib Lane After the Final Hook","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Record and position expressive vocal ad-libs around the climax chorus.  "}]},{"type":"step","title":"1. Ad-Lib Layer Architecture","blocks":[{"type":"prose","html":"On Track 2 (<code>VOX_ADLIBS</code>):"},{"type":"list","items":["Start recording on Bar 65 (Final Chorus).","Perform high-register falsetto runs, octave doublings, and emotional vocal answers that interlock between the main lead vocal phrases.","Pan Track 2 30% Left and insert a wide Ping-Pong delay to create a wide spatial halo around the centered lead vocal."],"ordered":false}]}],"minutes":8},{"id":"production-l11-1-4","title":"11.1.4 — Pocket Integrity: Avoiding Over-Quantization","blocks":[{"type":"step","title":"11.1.4 — Pocket Integrity: Avoiding Over-Quantization","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Protect organic human vocal groove from destructive grid quantization.  "}]},{"type":"step","title":"1. The Laid-Back Vocal Pocket","blocks":[{"type":"prose","html":"R&amp;B vocalists frequently sing slightly \"behind the beat\" (laid-back pocket):"},{"type":"list","items":["Hard-quantizing vocal transients to strict 16th-note gridlines strips away groove and soul.","When comping take lanes, preserve the natural phrasing and micro-timing of the performer."],"ordered":false}]}],"minutes":8},{"id":"production-l11-1-5","title":"11.1.5 — 32-Bar Linear R&B Sketch Assembly","blocks":[{"type":"step","title":"11.1.5 — 32-Bar Linear R&B Sketch Assembly","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Construct, audit, and export a complete 32-bar linear R&amp;B arrangement.  "}]},{"type":"step","title":"1. Arrangement Structure","blocks":[{"type":"list","items":["<code>01_Intro</code> (Bars 1–4): Filtered Rhodes piano + vinyl noise.","<code>02_Verse</code> (Bars 5–12): Sparse kick + finger snaps + comped vocal lead.","<code>03_Chorus</code> (Bars 13–20): Deep sub-bass + wide backing vocal stacks.","<code>04_Outro</code> (Bars 21–32): Ad-lib vocal runs over decaying electric piano chords."],"ordered":false}]}],"minutes":8},{"id":"production-l11-1-6","title":"11.1.6 — Authoring the R&B Space Documentation","blocks":[{"type":"step","title":"11.1.6 — Authoring the R&B Space Documentation","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Document vocal pauses and frequency headroom allocation in project notes.  "}]},{"type":"step","title":"1. Production Notes","blocks":[{"type":"prose","html":"Document in <code>RNB_SPACE_MAP.txt</code> how vocal rests and sub-bass headroom were managed across the linear timeline."}]}],"minutes":8},{"id":"production-l11-2-1","title":"11.2.1 — Drawing the Offbeat Skank on the Ruler","blocks":[{"type":"step","title":"11.2.1 — Drawing the Offbeat Skank on the Ruler","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Program authentic reggae/dub chord syncopation on the linear timeline.  "}]},{"type":"step","title":"1. Metric Offbeat Placement","blocks":[{"type":"prose","html":"In Reggae and Dub:"},{"type":"list","items":["The kick drum lands on Beat 3 (the One Drop) or all 4 beats (Steppers).","Guitar and organ \"skank\" chords land strictly on the <strong><code>&amp;</code> of every beat</strong> (1&amp;, 2&amp;, 3&amp;, 4&amp;).","Draw short, staccato 1/16th-length chords on the upbeats, leaving the downbeats open for the bassline."],"ordered":false}]}],"minutes":8},{"id":"production-l11-2-2","title":"11.2.2 — Delay Send Automation as Form","blocks":[{"type":"step","title":"11.2.2 — Delay Send Automation as Form","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Automate spatial delay throws to create classic dub echoes on phrase boundaries.  "}]},{"type":"step","title":"1. The Dub Throw Technique","blocks":[{"type":"prose","html":"In Dub music, the mixing desk is the lead instrument:"},{"type":"list","items":["Load Live's stock <strong>Delay</strong> device on Return Track A. Set to <strong>Dotted 8th (3)</strong>, Feedback at <strong>65%</strong>, Filter Bandpass active.","In Arrangement View, press <strong><code>A</code></strong> to open Automation.","On the Snare and Vocal tracks, select <strong>Send A</strong>.","Keep the send level at - dB for 7 bars.","On Bar 8 Beat 4, draw a sharp rectangular spike driving Send A to <strong>+4 dB</strong> on a single rimshot or vocal word.","<em>Result</em>: The snare hit detonates into a rolling, hypnotic echo that cascades across the subsequent 4 bars."],"ordered":true}]}],"minutes":8},{"id":"production-l11-2-3","title":"11.2.3 — Subtractive Stripping for the Dub Pass","blocks":[{"type":"step","title":"11.2.3 — Subtractive Stripping for the Dub Pass","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Slice out melodic instruments to spotlight bass and drums in isolation.  "}]},{"type":"step","title":"1. Sectional Deconstruction","blocks":[{"type":"prose","html":"On Bar 17 (The Dub Section):"},{"type":"list","items":["Splicing and deleting all guitars, pianos, and brass horns.","Only the sub-bassline and heavy drum kit continue playing.","The sudden absence of mid-range instruments creates a cavernous, hypnotic acoustic space."],"ordered":false}]}],"minutes":8},{"id":"production-l11-2-4","title":"11.2.4 — 32-Bar Linear Dub Sketch Assembly","blocks":[{"type":"step","title":"11.2.4 — 32-Bar Linear Dub Sketch Assembly","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Finalize, audit, and export a 32-bar linear dub arrangement.  "}]},{"type":"step","title":"1. Assembly and Export","blocks":[{"type":"prose","html":"Export <code>Linear_Dub_Sketch_v01.wav</code> (24-bit, 44.1 kHz)."}]}],"minutes":8},{"id":"production-l11-2-5","title":"11.2.5 — Documenting the Dub Throw Log","blocks":[{"type":"step","title":"11.2.5 — Documenting the Dub Throw Log","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Document exact bar timestamps of all automated delay throws.  "}]},{"type":"step","title":"1. Logging","blocks":[{"type":"prose","html":"Create <code>DUB_THROW_LIST.txt</code> listing the precise bar and beat coordinates of every automated delay throw."}]}],"minutes":8},{"id":"production-l11-2-6","title":"11.2.6 — Linear Automation vs. Live Session Dub Mixing","blocks":[{"type":"step","title":"11.2.6 — Linear Automation vs. Live Session Dub Mixing","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Compare drawing precision automation envelopes against live hardware fader riding.  "}]},{"type":"step","title":"1. Workflow Analysis","blocks":[{"type":"prose","html":"Compare the surgical precision of linear automation curves on the ruler against the spontaneous, organic performance of riding Launchkey MK4 faders live in Session View."}]}],"minutes":8},{"id":"production-l11-3-1","title":"11.3.1 — Selecting the Club Genre Spine","blocks":[{"type":"step","title":"11.3.1 — Selecting the Club Genre Spine","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Choose one electronic club genre to write directly on the linear timeline.  "}]},{"type":"step","title":"1. Target Genre Parameters","blocks":[{"type":"prose","html":"Select one core genre to compose on the ruler from Bar 1:"},{"type":"list","items":["<strong>House</strong>: 124–128 BPM · 4-on-the-Floor Kick · Offbeat Open Hats · Grooving Bass.","<strong>Techno</strong>: 130–135 BPM · Rumble Sub Kick · Hypnotic Repeating Synth Ostinato.","<strong>Dubstep (140)</strong>: 140 BPM · Halftime Kick/Snare on Beat 3 · Modulating Mid-Range Bass.","<strong>Drum &amp; Bass</strong>: 174 BPM · High-Speed Syncopated Breakbeat · Heavy Sub Bass."],"ordered":false}]}],"minutes":8},{"id":"production-l11-3-2","title":"11.3.2 — Mapping 32-Bar Linear Club Blocks with Locators","blocks":[{"type":"step","title":"11.3.2 — Mapping 32-Bar Linear Club Blocks with Locators","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Scaffold standard club arrangement blocks along the Beat-Time Ruler.  "}]},{"type":"step","title":"1. Linear Club Scaffolding","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">graph LR\n    DJIntro[\"01_DJ_Intro&lt;br&gt;Bars 1–32&lt;br&gt;Kick + Percussion\"] --&gt; Build[\"02_Build&lt;br&gt;Bars 33–48&lt;br&gt;Filter Sweeps + Risers\"]\n    Build --&gt; Drop1[\"03_MAIN_DROP&lt;br&gt;Bars 49–80&lt;br&gt;Full Bass + Groove\"]\n    Drop1 --&gt; Break[\"04_Breakdown&lt;br&gt;Bars 81–112&lt;br&gt;Atmosphere + Chords\"]\n    Break --&gt; Drop2[\"05_DROP_2&lt;br&gt;Bars 113–144&lt;br&gt;Max Energy + Leads\"]\n    Drop2 --&gt; DJOutro[\"06_DJ_Outro&lt;br&gt;Bars 145–176&lt;br&gt;Subtractive Outro\"]</pre>"}]}],"minutes":8},{"id":"production-l11-3-3","title":"11.3.3 — Additive and Subtractive Mute Automation","blocks":[{"type":"step","title":"11.3.3 — Additive and Subtractive Mute Automation","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Introduce and silence arrangement tracks across 8-bar blocks using Track Mute automation.  "}]},{"type":"step","title":"1. Mute Automation Mechanics","blocks":[{"type":"prose","html":"In Arrangement View, press <strong><code>A</code></strong> to open Automation:"},{"type":"list","items":["Select <strong>Mixer  Speaker On</strong> on each track.","Rather than slicing and deleting clips, draw binary ON/OFF automation blocks across 8-bar boundaries:","Bars 1–16: Kick + Closed Hats ON; Bass OFF; Synth OFF.","Bars 17–32: +Open Hi-Hats ON; +Percussion ON.","Bars 33–48: Kick OFF; Bass OFF; +Synth Riser ON.","Bar 49.1.1: ALL TRACKS ON (Drop Detonation)."],"ordered":false}]}],"minutes":8},{"id":"production-l11-3-4","title":"11.3.4 — Enforcing the 8-Bar Timeline Grid","blocks":[{"type":"step","title":"11.3.4 — Enforcing the 8-Bar Timeline Grid","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Align all structural shifts with visible 8-bar vertical grid lines.  "}]},{"type":"step","title":"1. Setting Fixed Grid to 8 Bars","blocks":[{"type":"list","items":["Right-click in the Arrangement timeline scrub area.","In the Grid context menu, select <strong>Fixed Grid  8 Bars</strong> (or 4 Bars).","Live displays bold vertical gridlines at Bars 1, 9, 17, 25, 33, 41, 49...","Ensure that every snare roll, riser sweep, and bass drop snaps precisely to these 8-bar boundaries."],"ordered":false}]}],"minutes":8},{"id":"production-l11-3-5","title":"11.3.5 — Linear Composition vs. Session Jamming","blocks":[{"type":"step","title":"11.3.5 — Linear Composition vs. Session Jamming","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Leverage linear-only capabilities: crossfades, long sweeps, and unique transitional audio.  "}]},{"type":"step","title":"1. Why Linear Composition Is NOT Just \"Session with Extra Steps\"","blocks":[{"type":"prose","html":"While Session View repeats static 8-bar loops, linear ruler writing allows:"},{"type":"list","items":["<strong>Continuous 32-Bar Modulation</strong>: Filter cutoff sweeps that evolve unbroken across 32 bars without looping.","<strong>Unique Non-Repeating Audio FX</strong>: Placing a single crash cymbal at Bar 49 that never repeats again.","<strong>Complex Crossfading</strong>: Blending the decaying reverb tail of the Breakdown smoothly across the Drop downbeat."],"ordered":true}]}],"minutes":8},{"id":"production-l11-3-6","title":"11.3.6 — Streaming-Length vs. Extended DJ-Length Pacing","blocks":[{"type":"step","title":"11.3.6 — Streaming-Length vs. Extended DJ-Length Pacing","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Formulate arrangements for radio streaming vs. club DJ utility.  "}]},{"type":"step","title":"1. Structural Comparison","blocks":[{"type":"list","items":["<strong>Streaming Radio Edit (2.5–3.5 minutes)</strong>: 8-bar short intro  Drop 1 arrives before 1:00  8-bar breakdown  Drop 2  8-bar outro.","<strong>Extended Club DJ Mix (5.5–7.0 minutes)</strong>: 32-bar unmelodic kick intro for beatmatching  16-bar buildup  32-bar Drop 1  32-bar melodic breakdown  64-bar Drop 2  32-bar outro."],"ordered":false}]}],"minutes":8},{"id":"production-l11-3-7","title":"11.3.7 — 64-Bar Linear Club Sketch Assembly","blocks":[{"type":"step","title":"11.3.7 — 64-Bar Linear Club Sketch Assembly","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Construct, audit, and export a complete 64-bar linear club arrangement.  "}]},{"type":"step","title":"1. Sketch Assembly","blocks":[{"type":"prose","html":"Construct a 64-bar timeline containing DJ Intro, Buildup, Main Drop, and Breakdown. Export <code>Linear_Club_Sketch_v01.wav</code>."}]}],"minutes":8},{"id":"production-l11-3-8","title":"11.3.8 — Documenting the Linear Energy Profile","blocks":[{"type":"step","title":"11.3.8 — Documenting the Linear Energy Profile","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Verify dynamic energy movement across the club timeline.  "}]},{"type":"step","title":"1. Documentation","blocks":[{"type":"prose","html":"Document the energy percentage milestones in <code>CLUB_LINEAR_NOTES.txt</code>."}]}],"minutes":8}],"exercises":[]}]};
